import { useState } from "react";
import type { SamplesState, TemplatesStatus } from "../hooks/useRuleTemplates";
import { cx } from "../lib/severity";
import { draftFromTemplate, usesAiQuota } from "../lib/templates";
import type { Rule, RuleCreate, RuleTemplate, RuleType, RuleUpdate } from "../types";
import RuleDetails from "./RuleDetails";
import RuleForm from "./RuleForm";
import TemplatePicker from "./TemplatePicker";
import { AiQuotaBadge, Button, ErrorNote, Icon, IconButton, Panel, PanelHeader, SeverityDot, Switch } from "./ui";

export interface TemplatesView {
  templates: RuleTemplate[];
  status: TemplatesStatus;
  error: string | null;
  onRetry: () => void;
}

export interface SamplesView extends SamplesState {
  onLoad: () => void;
  onDismiss: () => void;
}

interface Props {
  rules: Rule[];
  types: RuleType[];
  loading: boolean;
  error: string | null;
  onDismissError: () => void;
  onCreate: (input: RuleCreate) => Promise<void>;
  onUpdate: (id: number, changes: RuleUpdate) => Promise<void>;
  onToggle: (rule: Rule) => void;
  onDelete: (rule: Rule) => void;
  templates: TemplatesView;
  samples: SamplesView;
}

type Editing =
  | { kind: "new"; initial: RuleCreate | null; source: string | null }
  | { kind: "edit"; rule: Rule };

export default function RulesPanel({
  rules,
  types,
  loading,
  error,
  onDismissError,
  onCreate,
  onUpdate,
  onToggle,
  onDelete,
  templates,
  samples,
}: Props) {
  const [editing, setEditing] = useState<Editing | null>(null);
  const [formKey, setFormKey] = useState(0);
  const [viewingId, setViewingId] = useState<number | null>(null);

  /** A new key per opening, so the form state resets when another template or rule is picked. */
  function open(next: Editing) {
    setViewingId(null);
    setEditing(next);
    setFormKey((k) => k + 1);
  }

  const typeOf = (key: string) => types.find((t) => t.key === key);
  const templatesAvailable = templates.status !== "unavailable";
  // Look the rule up on every render, so the dialog reflects toggles and edits
  const viewing = rules.find((r) => r.id === viewingId) ?? null;
  const enabledCount = rules.filter((r) => r.enabled).length;

  return (
    <Panel className="flex flex-col gap-4 p-4" aria-labelledby="rules-heading">
      <PanelHeader id="rules-heading" title="Rules" count={rules.length}>
        <Button size="sm" icon="plus" onClick={() => open({ kind: "new", initial: null, source: null })} disabled={!types.length}>
          New rule
        </Button>
      </PanelHeader>

      <div className="flex flex-wrap items-start gap-2">
        <TemplatePicker
          templates={templates.templates}
          status={templates.status}
          error={templates.error}
          onRetry={templates.onRetry}
          onPick={(t) => open({ kind: "new", initial: draftFromTemplate(t), source: t.label })}
        />
        {templatesAvailable && (
          <Button variant="secondary" size="sm" icon="download" onClick={samples.onLoad} disabled={samples.loading}>
            {samples.loading ? "Loading samples…" : "Load Sample Rules"}
          </Button>
        )}
      </div>
      {!templatesAvailable && (
        <p className="text-xs text-slate-400">Rule templates and sample rules are not available on this server.</p>
      )}
      {samples.message && (
        <p role="status" className="flex items-center justify-between gap-2 rounded-xl bg-emerald-500/10 px-3 py-2 text-sm text-emerald-200 ring-1 ring-emerald-500/30">
          Sample rules: {samples.message}
          <IconButton icon="x" label="Dismiss" onClick={samples.onDismiss} className="-my-1 size-6" />
        </p>
      )}
      {samples.error && <ErrorNote onDismiss={samples.onDismiss}>{samples.error}</ErrorNote>}
      {error && <ErrorNote onDismiss={onDismissError}>{error}</ErrorNote>}

      {loading && <p className="text-sm text-slate-400">Loading rules…</p>}
      {!loading && !rules.length && (
        <div className="rounded-xl border border-dashed border-slate-700 px-4 py-6 text-center text-sm text-slate-400">
          No rules yet.
          <br />
          Create one, pick a template, or load the sample rules.
        </div>
      )}
      {rules.length > 0 && (
        <p className="-mb-2 text-xs text-slate-400">
          {enabledCount} of {rules.length} enabled · click a rule to see it
        </p>
      )}
      <ul className="flex flex-col gap-2" aria-label="Rules list">
        {rules.map((rule) => {
          const ai = usesAiQuota(rule);
          const instruction = ai && typeof rule.params.instruction === "string" ? rule.params.instruction : null;
          return (
            <li
              key={rule.id}
              className={cx(
                "group flex items-center gap-3 rounded-xl border bg-slate-800/50 pr-3 transition-colors hover:border-slate-500 hover:bg-slate-800",
                rule.enabled ? "border-slate-700" : "border-slate-800 opacity-70",
              )}
            >
              <button
                type="button"
                aria-haspopup="dialog"
                aria-label={`Open rule ${rule.name}`}
                className="flex min-w-0 flex-1 flex-col gap-1 rounded-xl py-3 pl-3 text-left"
                onClick={() => setViewingId(rule.id)}
              >
                <span className="flex items-center gap-2">
                  <SeverityDot severity={rule.severity} />
                  <span className="truncate text-sm font-semibold text-white" dir="auto" title={rule.name}>
                    {rule.name}
                  </span>
                </span>
                <span className="line-clamp-2 text-xs text-slate-400" dir="auto">
                  {instruction ?? typeOf(rule.type)?.label ?? rule.type}
                </span>
                {ai && (
                  <span className="mt-0.5">
                    <AiQuotaBadge />
                  </span>
                )}
              </button>
              <Switch checked={rule.enabled} onChange={() => onToggle(rule)} label={`Enable ${rule.name}`} size="sm" />
              <Icon name="chevron" className="size-4 shrink-0 text-slate-500 group-hover:text-slate-300" />
            </li>
          );
        })}
      </ul>

      {viewing && (
        <RuleDetails
          rule={viewing}
          type={typeOf(viewing.type)}
          onClose={() => setViewingId(null)}
          onEdit={() => open({ kind: "edit", rule: viewing })}
          onToggle={() => onToggle(viewing)}
          onDelete={() => onDelete(viewing)}
        />
      )}

      {editing && (
        <RuleForm
          key={formKey}
          types={types}
          rule={editing.kind === "edit" ? editing.rule : null}
          initial={editing.kind === "new" ? editing.initial : null}
          source={editing.kind === "new" ? editing.source : null}
          onCreate={onCreate}
          onUpdate={onUpdate}
          onDone={() => setEditing(null)}
        />
      )}
    </Panel>
  );
}
import { usesAiQuota } from "../lib/templates";
import type { Rule, RuleType } from "../types";
import { AiQuotaBadge, Button, DeleteButton, Modal, SeverityBadge, Switch } from "./ui";

interface Props {
  rule: Rule;
  type: RuleType | undefined;
  onClose: () => void;
  onEdit: () => void;
  onToggle: () => void;
  onDelete: () => void;
}

/** Read-only view of a rule, opened by clicking it in the rules list. */
export default function RuleDetails({ rule, type, onClose, onEdit, onToggle, onDelete }: Props) {
  const isAi = usesAiQuota(rule);
  const instruction = typeof rule.params.instruction === "string" ? rule.params.instruction : null;
  const params = Object.entries(rule.params).filter(([key]) => !(isAi && key === "instruction"));

  return (
    <Modal
      title={rule.name}
      subtitle={type?.label ?? rule.type}
      onClose={onClose}
      footer={
        <>
          <DeleteButton
            name={rule.name}
            onConfirm={() => {
              onDelete();
              onClose();
            }}
          />
          <span className="flex-1" />
          <Button icon="pencil" onClick={onEdit}>
            Edit rule
          </Button>
        </>
      }
    >
      <div className="flex flex-col gap-5">
        <div className="flex flex-wrap items-center gap-3">
          <SeverityBadge severity={rule.severity} />
          {isAi && <AiQuotaBadge />}
          <span className="flex-1" />
          <span className="flex items-center gap-2 text-sm text-slate-300">
            {rule.enabled ? "Enabled" : "Disabled"}
            <Switch checked={rule.enabled} onChange={onToggle} label={`Enable ${rule.name}`} />
          </span>
        </div>

        {instruction !== null && (
          <section>
            <h3 className="mb-2 text-xs font-semibold tracking-wider text-slate-400 uppercase">Rule</h3>
            <blockquote
              className="rounded-xl border-l-4 border-indigo-400 bg-slate-950 px-4 py-3 text-[0.95rem] leading-relaxed whitespace-pre-wrap text-slate-100"
              dir="auto"
            >
              {instruction}
            </blockquote>
          </section>
        )}

        {params.length > 0 && (
          <section>
            <h3 className="mb-2 text-xs font-semibold tracking-wider text-slate-400 uppercase">Settings</h3>
            <dl className="divide-y divide-slate-800 rounded-xl border border-slate-800 bg-slate-950">
              {params.map(([key, value]) => (
                <div key={key} className="grid grid-cols-[minmax(0,2fr)_minmax(0,3fr)] gap-3 px-4 py-2.5 text-sm">
                  <dt className="text-slate-400">{type?.params_schema.properties[key]?.title ?? key}</dt>
                  <dd className="font-medium break-words text-slate-100" dir="auto">
                    {formatValue(value)}
                  </dd>
                </div>
              ))}
            </dl>
          </section>
        )}

        {rule.description && (
          <section>
            <h3 className="mb-2 text-xs font-semibold tracking-wider text-slate-400 uppercase">Description</h3>
            <p className="text-sm text-slate-200" dir="auto">
              {rule.description}
            </p>
          </section>
        )}

        {type?.description && (
          <p className="rounded-xl bg-slate-800/60 px-4 py-3 text-sm text-slate-300">
            <span className="font-semibold text-slate-200">How this rule type works: </span>
            {type.description}
          </p>
        )}

        <p className="text-xs text-slate-500">Created {new Date(rule.created_at).toLocaleString()}</p>
      </div>
    </Modal>
  );
}

function formatValue(value: unknown): string {
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (Array.isArray(value)) return value.length ? value.join(", ") : "—";
  if (value === null || value === undefined || value === "") return "—";
  return String(value);
}
import { useRef } from "react";
import { DOCX_ACCEPT, formatSize } from "../lib/documents";
import { cx } from "../lib/severity";
import type { DocumentSummary } from "../types";
import { Button, DeleteButton, ErrorNote, Icon, Panel, PanelHeader } from "./ui";

interface Props {
  documents: DocumentSummary[];
  selectedId: number | null;
  loading: boolean;
  uploading: boolean;
  error: string | null;
  onSelect: (id: number) => void;
  onUpload: (file: File) => void;
  onDelete: (doc: DocumentSummary) => void;
}

export default function DocumentsPanel({
  documents,
  selectedId,
  loading,
  uploading,
  error,
  onSelect,
  onUpload,
  onDelete,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <Panel className="flex flex-col gap-4 p-4" aria-labelledby="documents-heading">
      <PanelHeader id="documents-heading" title="Documents" count={documents.length}>
        <Button size="sm" icon="upload" onClick={() => inputRef.current?.click()} disabled={uploading}>
          {uploading ? "Uploading…" : "Upload .docx"}
        </Button>
        <input
          ref={inputRef}
          type="file"
          accept={DOCX_ACCEPT}
          hidden
          aria-label="Upload .docx file"
          data-testid="upload-input"
          onChange={(e) => {
            const file = e.target.files?.[0];
            e.target.value = "";
            if (file) onUpload(file);
          }}
        />
      </PanelHeader>
      {error && <ErrorNote>{error}</ErrorNote>}
      {loading && <p className="text-sm text-slate-400">Loading documents…</p>}
      {!loading && !documents.length && (
        <p className="rounded-xl border border-dashed border-slate-700 px-4 py-6 text-center text-sm text-slate-400">
          No documents uploaded yet.
        </p>
      )}
      <ul className="flex flex-col gap-2" aria-label="Documents list">
        {documents.map((doc) => {
          const selected = doc.id === selectedId;
          return (
            <li
              key={doc.id}
              className={cx(
                "flex items-center gap-2 rounded-xl border pr-2 transition-colors",
                selected
                  ? "border-indigo-400/60 bg-indigo-500/15"
                  : "border-slate-700 bg-slate-800/50 hover:border-slate-500 hover:bg-slate-800",
              )}
            >
              <button
                type="button"
                className="flex min-w-0 flex-1 items-center gap-3 rounded-xl py-2.5 pl-3 text-left"
                aria-current={selected ? "true" : undefined}
                onClick={() => onSelect(doc.id)}
              >
                <Icon name="document" className={cx("size-5 shrink-0", selected ? "text-indigo-300" : "text-slate-500")} />
                <span className="min-w-0">
                  <span className="block truncate text-sm font-semibold text-white" dir="auto" title={doc.filename}>
                    {doc.filename}
                  </span>
                  <span className="block text-xs text-slate-400">
                    {formatSize(doc.size_bytes)} · {new Date(doc.uploaded_at).toLocaleString()}
                  </span>
                </span>
              </button>
              <DeleteButton compact name={doc.filename} onConfirm={() => onDelete(doc)} />
            </li>
          );
        })}
      </ul>
    </Panel>
  );
}
import { useRef, useState, type DragEvent } from "react";
import { DOCX_ACCEPT, formatSize } from "../lib/documents";
import { cx } from "../lib/severity";
import type { DocumentSummary } from "../types";
import { Button, Icon, Panel } from "./ui";

interface Props {
  documents: DocumentSummary[];
  rulesEnabled: number;
  uploading: boolean;
  onUpload: (file: File) => void;
  onSelect: (id: number) => void;
}

const RECENT = 5;

/** Main area when no document is open: drop zone + recent documents. */
export default function EmptyState({ documents, rulesEnabled, uploading, onUpload, onSelect }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  function onDrop(e: DragEvent) {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) onUpload(file);
  }

  return (
    <div className="flex flex-1 flex-col gap-4">
      <Panel className="flex flex-1 flex-col p-4 sm:p-6">
        <div
          onDragOver={(e) => {
            e.preventDefault();
            setDragging(true);
          }}
          onDragLeave={() => setDragging(false)}
          onDrop={onDrop}
          className={cx(
            "flex flex-1 flex-col items-center justify-center gap-4 rounded-xl border-2 border-dashed px-6 py-12 text-center transition-colors",
            dragging ? "border-indigo-400 bg-indigo-500/10" : "border-slate-700",
          )}
        >
          <span className="flex size-14 items-center justify-center rounded-2xl bg-indigo-500/15 text-indigo-300">
            <Icon name="upload" className="size-7" />
          </span>
          <div>
            <h2 className="text-xl font-semibold text-white">Check a Word document</h2>
            <p className="mt-1 text-sm text-slate-400">Drop a .docx file here, or choose one from your computer.</p>
          </div>
          <Button icon="upload" onClick={() => inputRef.current?.click()} disabled={uploading}>
            {uploading ? "Uploading…" : "Choose .docx file"}
          </Button>
          <input
            ref={inputRef}
            type="file"
            accept={DOCX_ACCEPT}
            hidden
            aria-label="Choose .docx file"
            onChange={(e) => {
              const file = e.target.files?.[0];
              e.target.value = "";
              if (file) onUpload(file);
            }}
          />
          <p className="text-xs text-slate-500">
            {rulesEnabled === 0
              ? "No rules are enabled yet: add or enable rules on the left before checking."
              : `${rulesEnabled} ${rulesEnabled === 1 ? "rule is" : "rules are"} enabled and will be checked.`}
          </p>
        </div>
      </Panel>

      {documents.length > 0 && (
        <Panel className="p-4" aria-labelledby="recent-heading">
          <h2 id="recent-heading" className="mb-3 text-sm font-semibold tracking-wide text-slate-200 uppercase">
            Recent documents
          </h2>
          <ul className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
            {documents.slice(0, RECENT).map((doc) => (
              <li key={doc.id}>
                <button
                  type="button"
                  onClick={() => onSelect(doc.id)}
                  className="flex w-full items-center gap-3 rounded-xl border border-slate-700 bg-slate-800/50 px-3 py-2.5 text-left transition-colors hover:border-slate-500 hover:bg-slate-800"
                >
                  <Icon name="document" className="size-5 shrink-0 text-slate-500" />
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-semibold text-white" dir="auto">
                      Open {doc.filename}
                    </span>
                    <span className="block text-xs text-slate-400">{formatSize(doc.size_bytes)}</span>
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </Panel>
      )}
    </div>
  );
}
import { useState } from "react";
import type { TemplatesStatus } from "../hooks/useRuleTemplates";
import { groupTemplates, usesAiQuota } from "../lib/templates";
import type { RuleTemplate } from "../types";
import { AiQuotaBadge, Button, ErrorNote, Icon, Modal, SeverityBadge } from "./ui";

interface Props {
  templates: RuleTemplate[];
  status: TemplatesStatus;
  error: string | null;
  onRetry: () => void;
  onPick: (template: RuleTemplate) => void;
}

/** "Add from template" button + picker dialog. Renders nothing when the server has no template endpoint. */
export default function TemplatePicker({ templates, status, error, onRetry, onPick }: Props) {
  const [open, setOpen] = useState(false);

  if (status === "unavailable") return null;
  if (status === "error") {
    return (
      <ErrorNote>
        Could not load rule templates: {error}{" "}
        <button type="button" className="font-semibold underline" onClick={onRetry}>
          Retry
        </button>
      </ErrorNote>
    );
  }

  const groups = groupTemplates(templates);

  return (
    <>
      <Button
        variant="secondary"
        size="sm"
        icon="template"
        aria-haspopup="dialog"
        disabled={status === "loading" || templates.length === 0}
        onClick={() => setOpen(true)}
      >
