@import "tailwindcss";

/*
 * Design tokens (Tailwind v4 CSS-first config). Utilities are generated from these, e.g.
 * `animate-flash`. The UI is monochrome (ADR-016): zinc greys, white surfaces, black accents.
 */
@theme {
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif;

  --animate-flash: flash 1.5s ease-out;

  @keyframes flash {
    0%,
    30% {
      background-color: rgb(24 24 27 / 0.14);
    }
    100% {
      background-color: rgb(24 24 27 / 0);
    }
  }
}

@layer base {
  html {
    color-scheme: light;
  }

  body {
    @apply bg-zinc-100 font-sans text-zinc-900 antialiased;
  }

  /* Visible keyboard focus only (never on mouse click) */
  :focus-visible {
    outline: 2px solid var(--color-zinc-900);
    outline-offset: 2px;
  }

  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]),
  mark[data-violation] {
    cursor: pointer;
  }

  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
  }
}

