// Screenshots of the redesigned UI. Reads existing data only; never triggers a check (no LLM calls).
import { chromium } from "playwright";

const out = process.argv[2];
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto("http://localhost:5199/");
await page.waitForTimeout(1500);
await page.screenshot({ path: `${out}/1-home.png` });

const docs = page.getByRole("list", { name: "Documents list" }).getByRole("button");
if ((await docs.count()) > 0) {
  await docs.first().click();
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${out}/2-report.png` });
  const card = page.getByRole("list", { name: "Violations list" }).getByRole("button").first();
  if (await card.count()) {
    await card.click();
    await page.waitForTimeout(1800);
    await page.screenshot({ path: `${out}/3-selected.png` });
  }
}
const rule = page.getByRole("button", { name: /^Open rule/ }).first();
if (await rule.count()) {
  await rule.click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${out}/4-rule-dialog.png` });
  await page.keyboard.press("Escape");
}
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/5-mobile.png` });
await browser.close();

